function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 50 : int(1, 8);
  const top = large ? 50 : 12;
  // A sequential run at the front, then values that often sit just above its sum.
  const start = int(1, top);
  const run = Math.min(n, int(1, large ? 8 : 4), 50 - start + 1);
  const nums = [];
  for (let i = 0; i < run; i++) nums.push(start + i);
  const sum = nums.reduce((a, b) => a + b, 0);
  while (nums.length < n) {
    const near = sum + int(0, 4);
    nums.push(rand() < 0.5 && near <= 50 ? near : int(1, top));
  }
  return [nums];
}
